try{const saved=JSON.parse(localStorage.getItem('jelly-pixels-hard-v1')||'{}');if(saved.scores&&typeof saved.scores==='object')scores=saved.scores;if(saved.eventBadges&&typeof saved.eventBadges==='object')eventBadges=saved.eventBadges;if(Number.isInteger(saved.stage))stage=Math.max(1,Math.min(STAGE_COUNT,saved.stage));}catch{}
